  for (index,(input,wanted,limbs)) in cases.iter().enumerate() {
    let got=digest033::checker_step(input[0],input[1],input[2],input[3],input[4],input[5],input[6],input[7]);
    assert_eq!(got,*wanted,"independent digest word vector {}",index);
    for limb in 0..4 {
      let actual=u64::from(got[2*limb]) | (u64::from(got[2*limb+1]) << 32);
      assert_eq!(actual,limbs[limb],"full digest limb vector {}:{}",index,limb);
    }
  }
  println!("passed {} full32-byte/four-u64 digest vectors",cases.len());
